package org.apache.commons.math.optimization.general;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.function.Function;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.OptimizationException;
import org.apache.commons.math3.optim.InitialGuess;
import org.apache.commons.math3.optim.PointValuePair;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;
import org.apache.commons.math3.optim.nonlinear.scalar.ObjectiveFunction;
import org.apache.commons.math3.optim.nonlinear.scalar.ObjectiveFunctionGradient;
import org.apache.commons.math3.optim.nonlinear.scalar.noderiv.AbstractLineSearchOptimizer;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.springframework.test.util.ReflectionTestUtils;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for LevenbergMarquardtOptimizer.doOptimize().
 * Since doOptimize is protected, we use a subclass or Reflection to access it.
 * Due to the complexity of the internal state (jacobian, residuals, etc.), 
 * we simulate different scenarios via the ObjectiveFunction.
 */
public class LevenbergMarquardtOptimizer_doOptimize_TriageGen1Test {

    // Helper class to access protected method
    private static class TestableLevenbergMarquardtOptimizer extends LevenbergMarquardtOptimizer {
        public PointValuePair doOptimizePublic() throws Exception {
            return super.doOptimize();
        }
    }

    /**
     * Test 1: Simple convergence case.
     * Minimizing f(x) = x^2. Residuals = x. Jacobian = 1.
     */
    @Test
    public void testDoOptimize_SimpleConvergence() throws Exception {
        TestableLevenbergMarquardtOptimizer optimizer = new TestableLevenbergMarquardtOptimizer();
        optimizer.setCostRelativeTolerance(1e-10);
        optimizer.setParRelativeTolerance(1e-10);
        optimizer.setOrthoTolerance(1e-10);

        // f(x) = x^2, residual = x. Jacobian = 1.
        // We use a MultivariateFunction to mimic the expected behavior of updateResidualsAndCost
        // Since the optimizer internally calls updateResidualsAndCost, we must provide a 
        // MultivariateJacobianFunction that behaves correctly.

        // In a real scenario, we'd mock the internal state. 
        // Here we use the standard public API to trigger doOptimize.

        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction function = new org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction() {
            @Override
            public org.apache.commons.math3.optim.Pair<Double, org.apache.commons.math3.util.Pair<double[], double[][]>> value(double[] point) {
                double val = point[0] * point[0];
                double[] residuals = {point[0]};
                double[][] jacobian = {{1.0}};
                return new org.apache.commons.math3.optim.Pair<>(val, new org.apache.commons.math3.util.Pair<>(residuals, jacobian));
            }
        };

        PointValuePair result = optimizer.optimize(
                new org.apache.commons.math3.optim.MaxEval(100),
                function,
                GoalType.MINIMIZE,
                new InitialGuess(new double[]{1.0})
        );

        Assert.assertEquals(0.0, result.getPoint()[0], 1e-5);
    }

    /**
     * Test 2: Test convergence via Orthogonality Tolerance.
     * When maxCosine <= orthoTolerance, it should return immediately.
     */
    @Test
    public void testDoOptimize_OrthoConvergence() throws Exception {
        TestableLevenbergMarquardtOptimizer optimizer = new TestableLevenbergMarquardtOptimizer();
        optimizer.setOrthoTolerance(1.0); // High tolerance to trigger early exit

        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction function = new org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction() {
            @Override
            public org.apache.commons.math3.optim.Pair<Double, org.apache.commons.math3.util.Pair<double[], double[][]>> value(double[] point) {
                // Force a state where maxCosine is small
                return new org.apache.commons.math3.optim.Pair<>(1.0, new org.apache.commons.math3.util.Pair<>(new double[]{1.0}, new double[][]{{0.0}}));
            }
        };

        PointValuePair result = optimizer.optimize(
                new org.apache.commons.math3.optim.MaxEval(10),
                function,
                GoalType.MINIMIZE,
                new InitialGuess(new double[]{1.0})
        );
        Assert.assertNotNull(result);
    }

    /**
     * Test 3: Test OptimizationException for too small cost relative tolerance.
     * This simulates the branch where actRed and preRed are extremely small.
     */
    @Test
    public void testDoOptimize_TooSmallCostRelativeTolerance() {
        TestableLevenbergMarquardtOptimizer optimizer = new TestableLevenbergMarquardtOptimizer();
        // Set tolerances to values that will trigger the machine epsilon check
        optimizer.setCostRelativeTolerance(1e-20);
        optimizer.setParRelativeTolerance(1e-20);
        optimizer.setOrthoTolerance(1e-20);

        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction function = new org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction() {
            @Override
            public org.apache.commons.math3.optim.Pair<Double, org.apache.commons.math3.util.Pair<double[], double[][]>> value(double[] point) {
                // Return values that lead to actRed/preRed being effectively zero
                return new org.apache.commons.math3.optim.Pair<>(1e-25, new org.apache.commons.math3.util.Pair<>(new double[]{1e-25}, new double[][]{{1.0}}));
            }
        };

        assertThrows(OptimizationException.class, () -> {
            optimizer.optimize(
                    new org.apache.commons.math3.optim.MaxEval(10),
                    function,
                    GoalType.MINIMIZE,
                    new InitialGuess(new double[]{1.0})
            );
        });
    }

    /**
     * Test 4: Test Convergence via Parameter Relative Tolerance.
     */
    @Test
    public void testDoOptimize_ParRelativeTolerance() throws Exception {
        TestableLevenbergMarquardtOptimizer optimizer = new TestableLevenbergMarquardtOptimizer();
        optimizer.setParRelativeTolerance(0.5); // Very large tolerance to trigger delta <= parRel * xNorm

        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction function = new org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction() {
            @Override
            public org.apache.commons.math3.optim.Pair<Double, org.apache.commons.math3.util.Pair<double[], double[][]>> value(double[] point) {
                return new org.apache.commons.math3.optim.Pair<>(1.0, new org.apache.commons.math3.util.Pair<>(new double[]{1.0}, new double[][]{{1.0}}));
            }
        };

        PointValuePair result = optimizer.optimize(
                new org.apache.commons.math3.optim.MaxEval(5),
                function,
                GoalType.MINIMIZE,
                new InitialGuess(new double[]{1.0})
        );
        Assert.assertNotNull(result);
    }

    /**
     * Test 5: Test the "failed iteration" logic (ratio < 1e-4).
     * This forces the inner loop to reset the point.
     */
    @Test
    public void testDoOptimize_FailedIteration() throws Exception {
        TestableLevenbergMarquardtOptimizer optimizer = new TestableLevenbergMarquardtOptimizer();

        // Function that increases cost when moving, forcing ratio to be low/negative
        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction function = new org.apache.commons.math3.optim.nonlinear.scalar.MultivariateJacobianFunction() {
            private int calls = 0;
            @Override
            public org.apache.commons.math3.optim.Pair<Double, org.apache.commons.math3.util.Pair<double[], double[][]>> value(double[] point) {
                calls++;
                if (calls == 1) {
                    return new org.apache.commons.math3.optim.Pair<>(10.0, new org.apache.commons.math3.util.Pair<>(new double[]{Math.sqrt(10.0)}, new double[][]{{1.0}}));
                } else {
                    // Increase cost to force ratio < 1e-4
                    return new org.apache.commons.math3.optim.Pair<>(20.0, new org.apache.commons.math3.util.Pair<>(new double[]{Math.sqrt(20.0)}, new double[][]{{1.0}}));
                }
            }
        };

        // We limit max evaluations to avoid infinite loop in the test
        assertThrows(org.apache.commons.math3.exception.ConvergenceException.class, () -> {
            optimizer.optimize(
                    new org.apache.commons.math3.optim.MaxEval(2),
                    function,
                    GoalType.MINIMIZE,
                    new InitialGuess(new double[]{1.0})
            );
        });
    }
}
